// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;
    function setUp() public { c = new StaxLPStaking(address(this), address(this)); }
    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        address originalOwner = c.owner();
        vm.assume(newOwner != originalOwner);
        vm.prank(msg.sender);
        bool ok;
        try c.transferOwnership(newOwner) { ok = true; } catch { ok = false; }
        if (msg.sender == originalOwner) {
            assertTrue(ok);
        } else {
            assertTrue(c.owner() == originalOwner);
        }
    }
}
